export const getSignupRequestsAcceptUrl = (applicationId: string,) => {




  return `/api/v1/signup-requests/${applicationId}/accept`
}

export const signupRequestsAccept = async (applicationId: string, options?: Parameters<typeof apiFetch>[1]): Promise<SignupAcceptResult> => {

  return apiFetch<SignupAcceptResult>(getSignupRequestsAcceptUrl(applicationId),
  {
    ...options,
    method: 'POST'


  }
);}





